const images=new Map();let manifest=null,pending=null;
export async function loadCharacterArt(onProgress=()=>{}){if(pending)return pending;pending=(async()=>{const response=await fetch(new URL('./art/characters/manifest.json',import.meta.url));if(!response.ok)throw new Error('Character artwork is unavailable');manifest=await response.json();const motionResponse=await fetch(new URL('./art/characters/drawn-manifest.json?v=clean-sprites-3',import.meta.url));if(!motionResponse.ok)throw new Error('Drawn animation sheets are unavailable');const drawn=await motionResponse.json();manifest.drawn=drawn;const preferred=Object.fromEntries(Object.entries(drawn.assets).filter(([key])=>key.includes('-hd-south')));const assets={...manifest.assets,...(Object.keys(preferred).length?preferred:drawn.assets)};let loaded=0;const total=Object.keys(assets).length;onProgress(0);await Promise.all(Object.entries(assets).map(async([key,entry])=>{const image=new Image();image.src=new URL('./art/characters/'+entry.file+'?v=clean-sprites-3',import.meta.url);await image.decode();images.set(key.replace('-hd-south','-south'),image);onProgress(++loaded/total);}));return manifest;})();return pending;}
export function characterImage(id,view='south',gear='blindfold',combat=false){const direction=view==='west'?'side':view;if(combat&&images.has(`${id}-combat`))return images.get(`${id}-combat`);if(id==='gojo'&&direction!=='north'){const special=images.get(`gojo-${direction}-${gear}`);if(special)return special;}return images.get(`${id}-${combat?'combat':direction}`)||images.get(`${id}-${direction}`)||images.get(`${id}-south`);}
export function characterManifest(){return manifest;}
